/**
 * Single-file package + Registry fixtures for Host V1 tests.
 *
 * Everything is generated into temp directories (no committed binaries) so
 * hashes/sizes always match the generated bytes.
 */

import { createHash } from 'node:crypto';
import { promises as fs } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';

/** 1×1 transparent PNG. */
export const PNG_BYTES = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==',
  'base64'
);

export const WEBP_BYTES = Buffer.from('UklGRiIAAABXRUJQVlA4IBYAAAAwAQCdASoBAAEAAUAmJaQAA3AA/vuUAAA=', 'base64');

export function sha256Hex(bytes) {
  return createHash('sha256').update(bytes).digest('hex');
}

export function buildManifest(overrides = {}) {
  return {
    manifestVersion: 1,
    id: 'jump',
    name: 'Jump',
    version: '1.0.0',
    author: { name: 'Test Studio' },
    description: 'A test game package used by host tests.',
    categories: ['arcade'],
    capabilities: ['storage', 'score'],
    sdkVersion: '^1.0.0',
    runtimeVersion: '^1.0.0',
    score: { direction: 'higher-better', min: 0, max: 1000000, integer: true },
    save: { schemaVersion: 1 },
    ...overrides,
  };
}

export function buildPackageHtml(manifest = buildManifest(), options = {}) {
  const inlineManifest = JSON.stringify(options.serializeManifest ? options.serializeManifest(manifest) : manifest, null, 2);
  const extra = options.extra || '';
  const manifestBlock = options.omitManifest
    ? ''
    : options.duplicateManifest
      ? `<script type="application/json" id="dsh-game-manifest">${inlineManifest}</script>\n<script type="application/json" id="dsh-game-manifest">${inlineManifest}</script>`
      : `<script type="application/json" id="dsh-game-manifest">${inlineManifest}</script>`;
  const bom = options.bom === true ? '\uFEFF' : '';
  return `${bom}<!doctype html>
<html lang="en" data-test-game="${manifest.id}">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>${manifest.name}</title>
    ${manifestBlock}
    <style>html, body { margin: 0; background: #0d1117; color: #f0f6fc; }</style>
  </head>
  <body data-test-entry="${manifest.id}">
    <div id="app"></div>
    <script>window.__GAME_FIXTURE__ = { id: '${manifest.id}', version: '${manifest.version}' };</script>
    ${extra}
  </body>
</html>
`;
}

export function buildPackage(manifest = buildManifest(), options = {}) {
  const html = options.html || buildPackageHtml(manifest, options);
  const bytes = Buffer.from(html, 'utf8');
  return { html, bytes, sha256: sha256Hex(bytes), size: bytes.length };
}

function registryEntryFor(manifest, pkg, overrides = {}, packageOverrides = {}) {
  return {
    id: manifest.id,
    name: manifest.name,
    version: manifest.version,
    description: manifest.description,
    author: { name: 'Test Studio' },
    categories: [...manifest.categories],
    tags: Array.isArray(manifest.tags) ? [...manifest.tags] : ['test', 'keyboard'],
    capabilities: [...manifest.capabilities],
    sdkVersion: manifest.sdkVersion,
    runtimeVersion: manifest.runtimeVersion,
    package: {
      url: pkg.url,
      sha256: pkg.sha256,
      size: pkg.size,
      releasedAt: '2026-10-18T00:00:00.000Z',
      ...packageOverrides,
    },
    cover: 'https://cdn.example.com/cover.png',
    publishedAt: '2026-10-18T00:00:00.000Z',
    updatedAt: '2026-10-18T00:00:00.000Z',
    ...overrides,
  };
}

function normaliseSpec(spec = {}) {
  const manifest = buildManifest({ ...(spec.manifest || {}) });
  return { manifest, spec };
}

/** Local file Registry (relative package paths inside the registry dir). */
export async function createFileRegistry(t, specs = []) {
  const directory = await fs.mkdtemp(path.join(tmpdir(), 'dsh-gm-registry-file-'));
  t.after(() => fs.rm(directory, { recursive: true, force: true }));
  const packagesDirectory = path.join(directory, 'packages');
  await fs.mkdir(packagesDirectory, { recursive: true });
  const indexPath = path.join(directory, 'games.json');
  const document = {
    registryVersion: 1,
    generatedAt: '2026-10-18T00:00:00.000Z',
    games: [],
  };

  async function add(spec = {}) {
    const { manifest } = normaliseSpec(spec);
    const pkg = buildPackage(manifest, spec.packageOptions || {});
    const fileName = `${manifest.id}-${manifest.version}.html`;
    const relative = `packages/${fileName}`;
    await fs.writeFile(path.join(directory, relative), pkg.bytes);
    const entry = registryEntryFor(
      manifest,
      { ...pkg, url: relative },
      spec.entry || {},
      spec.packageOverrides || {}
    );
    document.games.push(entry);
    return entry;
  }

  function remove(id) {
    document.games = document.games.filter((entry) => entry.id !== id);
  }

  async function writeIndex() {
    await fs.writeFile(indexPath, JSON.stringify(document, null, 2));
  }

  for (const spec of specs) await add(spec);
  await writeIndex();
  return { directory, indexPath, packagesDirectory, document, add, remove, writeIndex };
}

/**
 * HTTPS Registry served through an in-memory fetch stub.
 *
 * The index lives on `registry.example.com`; packages use GitHub-style URLs
 * that pass the default allowlist; preview assets live on `cdn.example.com`.
 */
export async function createHttpsRegistry(t, specs = [], options = {}) {
  const indexUrl = options.indexUrl || 'https://registry.example.com/games.json';
  const packageBase = options.packageBase || 'https://github.com/dsh-games/releases/download/v1.0.0';
  const directory = await fs.mkdtemp(path.join(tmpdir(), 'dsh-gm-registry-https-'));
  t.after(() => fs.rm(directory, { recursive: true, force: true }));
  const packages = new Map();
  const document = {
    registryVersion: 1,
    generatedAt: '2026-10-18T00:00:00.000Z',
    games: [],
  };
  const state = {
    etag: options.etag === undefined ? '"reg-1"' : options.etag,
    indexStatus: 200,
    indexFailures: 0,
    packageStatus: 200,
    packageFailures: 0,
    indexRequests: 0,
    packageRequests: 0,
    previewRequests: 0,
    previewOverrides: new Map(),
    indexBody: null,
  };

  async function add(spec = {}) {
    const { manifest } = normaliseSpec(spec);
    const pkg = buildPackage(manifest, spec.packageOptions || {});
    const fileName = `${manifest.id}-${manifest.version}.html`;
    const packageUrl = `${packageBase}/${fileName}`;
    packages.set(packageUrl, pkg);
    await fs.writeFile(path.join(directory, fileName), pkg.bytes);
    const entry = registryEntryFor(
      manifest,
      { ...pkg, url: packageUrl },
      {
        icon: `https://cdn.example.com/${manifest.id}/icon.png`,
        cover: `https://cdn.example.com/${manifest.id}/cover.png`,
        screenshots: [`https://cdn.example.com/${manifest.id}/shot-1.webp`],
        ...spec.entry,
      },
      spec.packageOverrides || {}
    );
    document.games.push(entry);
    return entry;
  }

  function remove(id) {
    document.games = document.games.filter((entry) => entry.id !== id);
  }

  function setIndex(documentValue) {
    document.registryVersion = documentValue.registryVersion;
    document.generatedAt = documentValue.generatedAt;
    document.games = documentValue.games;
  }

  async function fetchImpl(url, init = {}) {
    const href = String(url);
    const headers = new Headers(init.headers || {});
    if (href === indexUrl) {
      state.indexRequests += 1;
      if (state.indexFailures > 0) {
        state.indexFailures -= 1;
        throw new TypeError('simulated registry network failure');
      }
      if (state.indexStatus === 304) return new Response(null, { status: 304, headers: { etag: state.etag } });
      if (state.indexStatus !== 200) {
        return new Response('registry error', { status: state.indexStatus });
      }
      if (state.etag && headers.get('if-none-match') === state.etag) {
        return new Response(null, { status: 304, headers: { etag: state.etag } });
      }
      const body =
        state.indexBody === null ? JSON.stringify(document, null, 2) : state.indexBody;
      return new Response(body, {
        status: 200,
        headers: {
          'content-type': 'application/json; charset=utf-8',
          ...(state.etag ? { etag: state.etag } : {}),
        },
      });
    }
    const pkg = packages.get(href);
    if (pkg) {
      state.packageRequests += 1;
      if (state.packageFailures > 0) {
        state.packageFailures -= 1;
        throw new TypeError('simulated package network failure');
      }
      if (state.packageStatus !== 200) {
        return new Response('package error', { status: state.packageStatus });
      }
      return new Response(pkg.bytes, {
        status: 200,
        headers: { 'content-type': 'text/html; charset=utf-8', 'content-length': String(pkg.size) },
      });
    }
    if (href.startsWith('https://cdn.example.com/')) {
      state.previewRequests += 1;
      const override = state.previewOverrides.get(href);
      if (override) return override;
      return new Response(PNG_BYTES, {
        status: 200,
        headers: { 'content-type': 'image/png', 'content-length': String(PNG_BYTES.length) },
      });
    }
    return new Response('not found', { status: 404 });
  }

  for (const spec of specs) await add(spec);
  return {
    directory,
    indexUrl,
    packageBase,
    document,
    packages,
    state,
    fetch: fetchImpl,
    add,
    remove,
    setIndex,
  };
}

/** Minimal fetch stub used by Registry tests that only need a few responses. */
export function createFakeFetch(routes = []) {
  const calls = [];
  async function fetchImpl(url, init = {}) {
    const href = String(url);
    calls.push({ url: href, headers: new Headers(init.headers || {}) });
    for (const route of routes) {
      if (route.match !== undefined) {
        const matched =
          typeof route.match === 'string'
            ? route.match === href
            : route.match instanceof RegExp
              ? route.match.test(href)
              : route.match(href);
        if (!matched) continue;
      }
      const response = typeof route.response === 'function' ? await route.response(href, init) : route.response;
      if (response instanceof Response) return response;
      return new Response(response.body === undefined ? null : response.body, {
        status: response.status === undefined ? 200 : response.status,
        headers: response.headers || {},
      });
    }
    return new Response('not found', { status: 404 });
  }
  fetchImpl.calls = calls;
  return fetchImpl;
}

/** Read a package byte-for-byte from an install record. */
export async function readInstalledEntry(dataRoot, id, version) {
  return fs.readFile(path.join(dataRoot, 'packages', id, version, 'entry.html'));
}
